442	impl Debug for UniversePackages {
443	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
444	        f.debug_struct("Downloader")
445	            .field("url", &self.url)
446	            .finish_non_exhaustive()
447	    }
